    14→    ageMs < 0
    15→      ? "no data"
    16→      : ageMs < 1000
    17→        ? `${ageMs}ms ago`
    18→        : `${(ageMs / 1000).toFixed(1)}s ago`;
    19→
    20→  return (
    21→    <div className="flex items-center gap-2 rounded-md bg-gray-800/60 px-3 py-2">
