    24→          isReceiving ? "bg-green-400 animate-pulse" : "bg-gray-600"
    25→        }`}
    26→      />
    27→      <span className="text-xs text-gray-400">
    28→        Pioneer traffic:{" "}
    29→        <span className={isReceiving ? "text-green-400" : "text-gray-500"}>
    30→          {isReceiving ? `active · ${ageLabel}` : "none"}
    31→        </span>
    32→      </span>
    33→    </div>
    34→  );
    35→}
